import sys
MOD=998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    # For each prime, store its valuation on every adjacent edge.
    factors = {}
    for i, x in enumerate(a):
        z = x
        p = 2
        while p * p <= z:
            if z % p == 0:
                cnt = 0
                while z % p == 0:
                    z //= p
                    cnt += 1
                factors.setdefault(p, [0] * (n - 1))[i] = cnt
            p += 1 if p == 2 else 2
        if z > 1:
            factors.setdefault(z, [0] * (n - 1))[i] = 1

    answer = 1
    for prime, ds in factors.items():
        total = sum(ds)
        powers = [1] * (total + 1)
        for h in range(1, total + 1):
            powers[h] = powers[h - 1] * prime % MOD

        # Heights are normalized to have minimum zero. `yes` paths have
        # already visited height zero; `no` paths have not.
        no = [0] * (total + 1)
        yes = [0] * (total + 1)
        for h in range(total + 1):
            if h == 0:
                yes[h] = powers[h]
            else:
                no[h] = powers[h]

        for d in ds:
            next_no = [0] * (total + 1)
            next_yes = [0] * (total + 1)
            for h in range(total + 1):
                for src, touched in ((no, False), (yes, True)):
                    value = src[h]
                    if not value:
                        continue
                    # If this prime is absent on the edge, there is one
                    # transition; otherwise the valuation difference has
                    # two possible signs.
                    destinations = (h,) if d == 0 else (h - d, h + d)
                    for nh in destinations:
                        if 0 <= nh <= total:
                            contribution = value * powers[nh] % MOD
                            if touched or nh == 0:
                                next_yes[nh] = (next_yes[nh] + contribution) % MOD
                            else:
                                next_no[nh] = (next_no[nh] + contribution) % MOD
            no, yes = next_no, next_yes

        answer = answer * (sum(yes) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    main()

