    values = data[1:]
    limit = max(values)

    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for multiple in range(p * p, limit + 1, p):
                if spf[multiple] == multiple:
                    spf[multiple] = p

    nim_sum = 0
    for value in values:
        factors = 0
        while value > 1:
            p = spf[value]
            while value % p == 0:
                value //= p
                factors += 1
        nim_sum ^= factors

    print('Anna' if nim_sum else 'Bruno')

