from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        starts = [[] for _ in range(n + 1)]
        for idx, (x, y) in enumerate(conflictingPairs):
            a, b = sorted((x, y))
            starts[b].append((a, idx))

        top1 = top2 = 0
        top_id = -1
        gain = [0] * len(conflictingPairs)
        total = 0

        for right in range(1, n + 1):
            for a, idx in starts[right]:
                if a > top1:
                    top2 = top1
                    top1 = a
                    top_id = idx
                elif a > top2:
                    top2 = a

            total += right - top1
            if top_id != -1:
                gain[top_id] += top1 - top2

        return total + max(gain)

