class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        starts = [[] for _ in range(n + 1)]
        for idx, (x, y) in enumerate(conflictingPairs):
            a, b = sorted((x, y))
            starts[b].append((a, idx))
        top1 = top2 = 0
        who = -1
        gain = [0] * len(conflictingPairs)
        total = 0
        for r in range(1, n + 1):
            for a, idx in starts[r]:
                if a > top1:
                    top2 = top1
                    top1, who = a, idx
                elif a > top2:
                    top2 = a
            total += r - top1
            if who >= 0:
                gain[who] += top1 - top2
        return total + max(gain, default=0)

