N,M,Q=map(int,input().split())
edges=[None]
for _ in range(M):
    a,b,c=map(int,input().split())
    edges.append((a-1,b-1,c))
queries=[]
closed=[False]*(M+1)
for _ in range(Q):
    t,*v=map(int,input().split())
    queries.append((t,*v))
    if t==1:
        closed[v[0]]=True

INF=10**30
d=[[INF]*N for _ in range(N)]
for i in range(N):
    d[i][i]=0
for i in range(1,M+1):
    if not closed[i]:
        a,b,c=edges[i]
        d[a][b]=d[b][a]=c

for k in range(N):
    dk=d[k]
    for i in range(N):
        dik=d[i][k]
        if dik==INF:
            continue
        di=d[i]
        for j in range(N):
            nd=dik+dk[j]
            if nd<di[j]:
                di[j]=nd

answers=[]
for query in reversed(queries):
    if query[0]==2:
        _,x,y=query
        value=d[x-1][y-1]
        answers.append(str(value if value<INF else -1))
    else:
        idx=query[1]
        a,b,w=edges[idx]
        da=[d[i][a] for i in range(N)]
