            di=d[i]
            via_ab=da[i]+w
            via_ba=db[i]+w
            for j in range(N):
                nd1=via_ab+db[j]
                nd2=via_ba+da[j]
                if nd1<di[j]:
                    di[j]=nd1
                if nd2<di[j]:
                    di[j]=nd2
print('\n'.join(reversed(answers)))

