import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]; a=data[1:]
    pref=[0]*(n+1); seen=set()
    for i,x in enumerate(a,1):
        seen.add(x); pref[i]=len(seen)
    suf=[0]*(n+2); seen.clear()
    for i in range(n,0,-1):
        seen.add(a[i-1]); suf[i]=len(seen)
    size=1
    while size<n+1: size*=2
    mx=[0]*(2*size); lazy=[0]*(2*size)
    for i in range(1,n+1): mx[size+i-1]=pref[i]
    for k in range(size-1,0,-1): mx[k]=max(mx[2*k],mx[2*k+1])
    def add(node,l,r,ql,qr,v):
        if ql<=l and r<=qr:
            mx[node]+=v; lazy[node]+=v; return
        mid=(l+r)//2
        if ql<=mid: add(node*2,l,mid,ql,qr,v)
        if qr>mid: add(node*2+1,mid+1,r,ql,qr,v)
        mx[node]=lazy[node]+max(mx[node*2],mx[node*2+1])
    def query(node,l,r,ql,qr,carry=0):
        if ql<=l and r<=qr: return mx[node]+carry
        carry+=lazy[node]; mid=(l+r)//2
        ans=-10**9
        if ql<=mid: ans=max(ans,query(node*2,l,mid,ql,qr,carry))
        if qr>mid: ans=max(ans,query(node*2+1,mid+1,r,ql,qr,carry))
        return ans
    last=[0]*(n+1); ans=0
    for j,x in enumerate(a,1):
        p=last[x]
        if j>=2:
            lo=max(1,p); hi=j-1
            if lo<=hi: add(1,1,size,lo,hi,1)
            if j>=2: ans=max(ans,query(1,1,size,1,j-1)+suf[j+1])
        last[x]=j
    print(ans)
