import sys
import math

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    processes = []
    pos = 2

    for _ in range(n):
        a, p, b, q = data[pos:pos + 4]
        pos += 4
        g = math.gcd(a, b)

        # Bundles of b/g S-machines and a/g T-machines have equal capacity.
        # Enumerate the count of the more expensive bundle's machine type;
        # an optimum never needs a full such bundle.
        if p * (b // g) >= q * (a // g):
            processes.append((a, p, b, q, b // g, True))
        else:
            processes.append((a, p, b, q, a // g, False))

    def minimum_cost(proc, target):
        a, p, b, q, limit, enumerate_s = proc
        best = 10**30
        if enumerate_s:
            for s in range(limit):
                remaining = target - a * s
                t = max(0, (remaining + b - 1) // b)
                best = min(best, s * p + t * q)
        else:
            for t in range(limit):
                remaining = target - b * t
                s = max(0, (remaining + a - 1) // a)
                best = min(best, t * q + s * p)
        return best

    def feasible(target):
        total = 0
        for proc in processes:
            total += minimum_cost(proc, target)
            if total > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

