class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        def depth(c):
            d = 0
            while c > 1:
                c = c.bit_count()
                d += 1
            return d

        choose = [[0] * (n + 1) for _ in range(n + 1)]
        choose[0][0] = 1
        for a in range(1, n + 1):
            choose[a][0] = choose[a][a] = 1
            for b in range(1, a):
                choose[a][b] = (choose[a - 1][b - 1] + choose[a - 1][b]) % MOD

        ans = 0
        for target in range(1, n + 1):
            # One operation takes x to its popcount, followed by depth(target).
            if 1 + depth(target) > k:
                continue
            used = 0
            ways = 0
            for i, bit in enumerate(s):
                rem = n - i - 1
                if bit == '1':
                    need = target - used
                    if 0 <= need <= rem:
                        ways += choose[rem][need]
                    used += 1
                    if used > target:
                        break
            ans = (ans + ways) % MOD
        return ans

