import sys
from collections import deque

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    N, M, Q = next(it), next(it), next(it)
    people = [(next(it), next(it)) for _ in range(M)]
    queries = [(next(it), next(it)) for _ in range(Q)]
    answers = []

    for L, R in queries:
        parent = list(range(N + 1))
        size = [1] * (N + 1)

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        # Endpoint potentials of each selected person must be equal.
        for i in range(L - 1, R):
            a, b = people[i]
            x, y = find(a), find(b)
            if x != y:
                if size[x] < size[y]:
                    x, y = y, x
                parent[y] = x
                size[x] += size[y]

        # Strict inequalities form a directed graph on equality classes.
        adj = [[] for _ in range(N + 1)]
        indegree = [0] * (N + 1)
        contradiction = False
        for i in range(L - 1, R):
            a, b = people[i]
            endpoint = find(a)
            if a < b:
                # Every interior potential must be strictly greater.
                for v in range(a + 1, b):
                    z = find(v)
                    if z == endpoint:
                        contradiction = True
                        break
                    adj[endpoint].append(z)
                    indegree[z] += 1
            else:
                # Traveling left, every interior potential must be strictly less.
                for v in range(b + 1, a):
                    z = find(v)
                    if z == endpoint:
                        contradiction = True
                        break
                    adj[z].append(endpoint)
                    indegree[endpoint] += 1
            if contradiction:
                break

        if contradiction:
            answers.append('No')
            continue

        roots = {find(v) for v in range(1, N + 1)}
        queue = deque(v for v in roots if indegree[v] == 0)
        visited = 0
        while queue:
            u = queue.popleft()
            visited += 1
            for v in adj[u]:
                indegree[v] -= 1
                if indegree[v] == 0:
                    queue.append(v)
        answers.append('Yes' if visited == len(roots) else 'No')

    sys.stdout.write('\n'.join(answers))

if __name__ == '__main__':
    main()

