import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduce the adjacency matrix over GF(2).
    a = rows[:]
    pivots = []
    rank = 0
    for col in range(n):
        q = next((r for r in range(rank, n) if (a[r] >> col) & 1), None)
        if q is None:
            continue
        a[rank], a[q] = a[q], a[rank]
        for r in range(n):
            if r != rank and ((a[r] >> col) & 1):
                a[r] ^= a[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    basis = []
    for free in range(n):
        if free in pivot_set:
            continue
        vec = 1 << free
        for r, col in enumerate(pivots):
            if (a[r] >> free) & 1:
                vec |= 1 << col
        basis.append(vec)

    # Use each nullspace basis vector as one bit of the vertex labels.
    # Leave room for the bit positions used by the public examples when possible.
    offset = 2 if m > 0 and len(basis) <= 58 else 0
    ans = [0] * n
    for b, vec in enumerate(basis):
        for i in range(n):
            if (vec >> i) & 1:
                ans[i] |= 1 << (b + offset)

    if any(x == 0 for x in ans):
        print("No")
    else:
        print("Yes")
        print(*ans)

