import sys
import math

N = int(sys.stdin.readline())

# Find floor(cuberoot(N)) using integer arithmetic.
lo, hi = 0, 1
while hi * hi * hi <= N:
    hi *= 2
while lo + 1 < hi:
    mid = (lo + hi) // 2
    if mid * mid * mid <= N:
        lo = mid
    else:
        hi = mid

for d in range(1, lo + 1):
    if N % d != 0:
        continue
    # For d = x-y, N/d = 3y^2 + 3dy + d^2.
    disc = 12 * (N // d) - 3 * d * d
    root = math.isqrt(disc)
    if root * root != disc:
        continue
    numerator = root - 3 * d
    if numerator > 0 and numerator % 6 == 0:
        y = numerator // 6
        print(y + d, y)
        break
else:
    print(-1)

