from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = set(range(1, n + 1, 2))
        evens = set(range(2, n + 1, 2))

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        def ways(o: int, e: int, next_parity: int) -> int:
            length = o + e
            if length == 0:
                return 1
            if next_parity == 1:
                need_o = (length + 1) // 2
                need_e = length // 2
            else:
                need_e = (length + 1) // 2
                need_o = length // 2
            if o != need_o or e != need_e:
                return 0
            return fact[o] * fact[e]

        answer = []
        last_parity = None
        while len(answer) < n:
            found = False
            for value in sorted(odds | evens):
                parity = value % 2
                if last_parity is not None and parity == last_parity:
                    continue

                remaining_odds = len(odds) - (parity == 1)
                remaining_evens = len(evens) - (parity == 0)
                block = ways(remaining_odds, remaining_evens, 1 - parity)

                if k > block:
                    k -= block
                else:
                    answer.append(value)
                    if parity == 1:
                        odds.remove(value)
                    else:
                        evens.remove(value)
                    last_parity = parity
                    found = True
                    break

            if not found:
                return []

        return answer

