class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n=len(nums)
        nxt=[n]*n
        st=[]
        for i in range(n-1,-1,-1):
            while st and nums[st[-1]] <= nums[i]: st.pop()
            nxt[i]=st[-1] if st else n
            st.append(i)
        LOG=n.bit_length()
        jump=[nxt]
        agg=[[nums[i]*(nxt[i]-i) for i in range(n)]]
        for p in range(1,LOG):
            prev=jump[-1]; pa=agg[-1]
            jp=[n]*n; ap=[0]*n
            for i in range(n):
                m=prev[i]
                if m<n:
                    jp[i]=prev[m]
                    ap[i]=pa[i]+pa[m]
                else: ap[i]=pa[i]
            jump.append(jp); agg.append(ap)
        pref=[0]
        for x in nums: pref.append(pref[-1]+x)
        def cost(l,r):
            node=l; total=0
            for p in range(LOG-1,-1,-1):
                dest=jump[p][node]
                if dest<=r:
                    total+=agg[p][node]
                    node=dest
            total+=nums[node]*(r-node+1)
            return total-(pref[r+1]-pref[l])
        ans=0; r=-1
        for l in range(n):
            if r<l: r=l
            while r+1<n and cost(l,r+1)<=k: r+=1
            ans+=r-l+1
        return ans

