import sys
from functools import cmp_to_key

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    funcs = [(data[2 + 2*i], data[3 + 2*i]) for i in range(n)]

    # In an optimal arrangement, functions are applied from lower (A-1)/B
    # to higher (A-1)/B. Compare ratios exactly by cross multiplication.
    def compare(x, y):
        left = (x[0] - 1) * y[1]
        right = (y[0] - 1) * x[1]
        return (left > right) - (left < right)

    funcs.sort(key=cmp_to_key(compare))

    # dp[j] is the maximum value after choosing j functions among the
    # processed prefix, with their required sorted order applied.
    dp = [None] * (k + 1)
    dp[0] = 1
    processed = 0
    for a, b in funcs:
        for j in range(min(k - 1, processed), -1, -1):
            if dp[j] is not None:
                value = a * dp[j] + b
                if dp[j + 1] is None or value > dp[j + 1]:
                    dp[j + 1] = value
        processed += 1

    print(dp[k])

if __name__ == '__main__':
    main()

