            # state: previous letter absent/present, and whether any letter is present
            dp=[[10**9]*2 for _ in range(2)]
            for q in (0,1):
                dp[q][q]=a[0] if not q else abs(a[0]-k)
            for i in range(1,26):
                ndp=[[10**9]*2 for _ in range(2)]
                for p in (0,1):
                    for seen in (0,1):
                        if dp[p][seen]>=10**9: continue
                        for q in (0,1):
                            cost=a[i] if not q else abs(a[i]-k)
                            edge=0
                            if p and q and a[i-1]>k and a[i]<k:
                                edge=min(a[i-1]-k,k-a[i])
                            ns=seen or q
                            ndp[q][ns]=min(ndp[q][ns],dp[p][seen]+cost-edge)
                dp=ndp
            ans=min(ans,dp[0][1],dp[1][1])
        return ans

