class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        parent[0] = 0
        order = [0]
        for node in order:
            for neighbor, _ in graph[node]:
                if neighbor != parent[node]:
                    parent[neighbor] = node
                    order.append(neighbor)

        # dp0[v]: best subtree value when the edge to its parent is removed.
        # dp1[v]: best subtree value when the edge to its parent is retained.
        dp0 = [0] * n
        dp1 = [0] * n
        for node in reversed(order):
            base = 0
            gains = []
            for child, weight in graph[node]:
                if parent[child] == node:
                    base += dp0[child]
                    gain = weight + dp1[child] - dp0[child]
                    if gain > 0:
                        gains.append(gain)
            gains.sort(reverse=True)
            prefix = [0]
            for gain in gains:
                prefix.append(prefix[-1] + gain)
            dp0[node] = base + prefix[min(k, len(gains))]
            dp1[node] = base + prefix[min(k - 1, len(gains))]

        return dp0[0]

