    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        from bisect import bisect_right, bisect_left
        n = len(s)
        a, b, c = p.split('*')

        def occurrences(t):
            if not t:
                return list(range(n + 1))
            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    out.append(i - m + 1)
                    j = pi[j - 1]
            return out

        oa, ob, oc = occurrences(a), occurrences(b), occurrences(c)
        best = n + 1
        for x in ob:
            be = x + len(b)
            if a:
                k = bisect_right(oa, x - len(a)) - 1
                if k < 0:
                    continue
                start = oa[k]
            else:
                start = x
            if c:
                k = bisect_left(oc, be)
                if k == len(oc):
                    continue
                end = oc[k] + len(c)
            else:
                end = be
            best = min(best, end - start)
        return best if best <= n else -1

