import sys

def main():
    data = sys.stdin.buffer.read().split()
    K = int(data[0])
    s = data[1].decode()
    t = data[2].decode()
    n, m = len(s), len(t)

    if abs(n - m) > K:
        print("No")
        return

    inf = K + 1
    prev = [inf] * (m + 1)
    cur = [inf] * (m + 1)
    hi = min(m, K)
    for j in range(hi + 1):
        prev[j] = j

    for i in range(1, n + 1):
        lo = max(0, i - K)
        hi = min(m, i + K)
        prev_lo = max(0, i - 1 - K)
        prev_hi = min(m, i - 1 + K)
        sc = s[i - 1]
        row_min = inf

        for j in range(lo, hi + 1):
            best = inf
            if prev_lo <= j <= prev_hi:
                v = prev[j] + 1
                if v < best:
                    best = v
            if j > lo:
                v = cur[j - 1] + 1
                if v < best:
                    best = v
            if j > 0 and prev_lo <= j - 1 <= prev_hi:
                v = prev[j - 1] + (sc != t[j - 1])
                if v < best:
                    best = v

            if best > inf:
                best = inf
            cur[j] = best
            if best < row_min:
                row_min = best

        if row_min > K:
            print("No")
            return
        prev, cur = cur, prev

    print("Yes" if prev[m] <= K else "No")

if __name__ == "__main__":
    main()

